<template>
    <el-card>
        <el-tabs v-model="unOrEd" :tab-position="tabPosition">
            <el-tab-pane label="未评分的作品" name="un">
                <el-table :data="unMarkProjects" style="width: 100%">
                    <el-table-column type="expand">
                        <template slot-scope="props">
                            <el-form label-position="right"
                                     style="background-color: rgba(146,255,152,0.58);border-radius: 20px">
                                <el-form-item inline v-for="(workFile,index) in props.row.workFiles" :key="workFile.id">
                                    <el-row :gutter="40">
                                        <el-col :span="2"><span style="color: #1402bf;float: right">{{ fileTip+String((index+1))}}</span>
                                        </el-col>
                                        <el-col :span="10"><span>{{ workFile.fileName}}</span></el-col>
                                        <el-col :span="3"><a :href='api+"/file/downloadFile/"+workFile.id'>
                                            <el-link icon="el-icon-download" :underline="false">下载附件</el-link>
                                        </a></el-col>
                                    </el-row>
                                </el-form-item>
                            </el-form>
                        </template>
                    </el-table-column>
                    <el-table-column label="竞赛 ID" prop="project.comp.id"></el-table-column>
                    <el-table-column label="竞赛名" prop="project.comp.compName"></el-table-column>
                    <el-table-column label="队伍名" prop="project.projectName"></el-table-column>
                    <el-table-column label="作品名" prop="workName"></el-table-column>
                    <el-table-column label="评分">
                        <template slot-scope="scope">
                            <el-input v-model="input" size="mini" style="width: 50px;margin-right: 20px"
                                      :id=work+scope.row.id></el-input>
                            <el-popconfirm title="确认评分吗？" @confirm="markWork(scope.row.id)">
                                <el-button type="success" size="mini" slot="reference">保存</el-button>
                            </el-popconfirm>
                        </template>
                    </el-table-column>
                </el-table>
            </el-tab-pane>
            <el-tab-pane label="已评分的作品" name="ed">
                <el-table :data="markWorkProjects" style="width: 100%">
                    <el-table-column type="expand">
                        <template slot-scope="props">
                            <el-form label-position="right"
                                     style="background-color: rgba(146,255,152,0.58);border-radius: 20px">
                                <el-form-item inline v-for="(work,index) in props.row.projectList" :key="work.id">
                                    <el-row :gutter="40">
                                        <el-col :span="2"><span style="color: #1402bf;float: right">名次：{{String((index+1))}}</span>
                                        </el-col>
                                        <el-col :span="5"><span>作品名：{{work.workName}}</span></el-col>
                                        <el-col :span="6"><span>评分:{{work.score}}</span></el-col>
                                        <el-col :span="4">
                                            <!--                                                                                        <el-button type="primary" @click="awardFormVisible=true,setAwardFormData(work.workName,work.project)">评奖</el-button>-->
                                            <el-button type="primary"
                                                       @click="checkAwards(work.project.id,work.workName,work.project)">
                                                评奖
                                            </el-button>
                                        </el-col>
                                        <el-col :span="4">
                                            <template v-if="awards.length > 0">
                                                <span v-for="(award, index) in awards" :key="index">
                                                   获奖情况: {{ getAwardName(award.level) }}
                                                </span>
                                            </template>
                                            <span v-else>暂无获奖情况</span>
                                        </el-col>
                                    </el-row>
                                </el-form-item>
                            </el-form>
                        </template>
                    </el-table-column>
                    <el-table-column label="竞赛 ID" prop="compId"></el-table-column>
                    <el-table-column label="竞赛名" prop="compName"></el-table-column>
                    <el-table-column label="截至报名日期" prop="notApplyTime">
                        <template slot-scope="scope">
                            {{scope.row.notApplyTime|dataTime}}
                        </template>
                    </el-table-column>
                    <el-table-column label="比赛时间" prop="occurrenceTime">
                        <template slot-scope="scope">
                            {{scope.row.occurrenceTime|dataTime}}
                        </template>
                    </el-table-column>
                </el-table>
            </el-tab-pane>
        </el-tabs>

        <!-- 评奖信息表单对话框 -->
        <el-dialog title="填写获奖信息" :visible.sync="awardFormVisible">
            <el-form :model="awardForm" label-width="80px">
                <el-form-item label="获奖队伍">
                    <el-input v-model="awardForm.compName"></el-input>
                </el-form-item>
                <el-form-item label="获奖作品">
                    <el-input v-model="awardForm.work"></el-input>
                </el-form-item>
                <el-form-item label="奖项名次">
                    <el-select v-model="awardForm.level" placeholder="请选择获奖名次">
                        <el-option label="一等奖" value="4"></el-option>
                        <el-option label="二等奖" value="3"></el-option>
                        <el-option label="三等奖" value="2"></el-option>
                        <el-option label="参与奖" value="1"></el-option>
                    </el-select>
                </el-form-item>
                <el-form-item label="获奖级别">
                    <el-select v-model="awardForm.type" placeholder="请选择获奖级别">
                        <el-option label="国家级" value="4"></el-option>
                        <el-option label="省级" value="3"></el-option>
                        <el-option label="校级" value="2"></el-option>
                        <el-option label="其他" value="1"></el-option>
                    </el-select>
                </el-form-item>
                <el-form-item label="获奖日期">
                    <el-date-picker v-model="awardForm.date" type="date"></el-date-picker>
                </el-form-item>
<!--                <el-form-item label="奖状">-->
<!--                    <el-upload :action="imageUrl" :on-exceed="uploadAwardSuccess">-->
<!--                        <el-button size="small" type="primary">点击上传</el-button>-->
<!--                    </el-upload>-->
<!--                </el-form-item>-->
                <el-form-item>
                    <el-button type="primary" @click="submitAwardForm">提交</el-button>
                    <el-button type="danger" @click="awardFormVisible = false">取消</el-button>
                </el-form-item>
            </el-form>
        </el-dialog>
    </el-card>
</template>

<script>
    import api from '../../main'

    export default {
        name: "college_work",
        inject: ['reload'],
        data() {
            return {
                work: "work",
                input: 0,
                file: "",
                fileTip: "附件",
                api: api,
                tabPosition: "left",
                unOrEd: "un",
                imageUrl:api+'/file/upload',
                unMarkProjects: [],
                markWorkProjects: [],
                awards: [],
                awardFormVisible: false, // 控制获奖信息表单的显示状态
                awardForm: {  // 获奖信息表单数据
                    compName: '',
                    level: '',
                    date: '',
                    type: '',
                    work: '',
                    img:'',
                    project: [],
                }
            }
        },

        mounted() {
            this.getUnMarkProjects();
            this.getMarkWorkProjects();
            this.checkAwards();
        },
        methods: {
            getMarkWorkProjects() {
                let that = this;
                that.$axios
                    .get(api + '/college/getMarkWorkProjects/' + that.$store.state.id)
                    .then(function (response) {
                        that.markWorkProjects = response.data;
                        console.log(that.markWorkProjects);
                    });

            },

            getUnMarkProjects() {
                let that = this;
                that.$axios
                    .get(api + '/college/getUnMarkProjects/' + that.$store.state.id)
                    .then(function (response) {
                        that.unMarkProjects = response.data;
                    })
            },

            markWork(workId) {
                let that = this;
                let id = this.work + workId;
                let score = document.getElementById(id).value;
                if (score <= 0) {
                    that.$message.error(score + "分实在太低了！请重新打分");
                } else if (score >= 100) {
                    that.$message.error("请在1-99分中评分！");
                } else {
                    that.$axios
                        .get(api + "/college/markWork/" + score + "/" + workId)
                        .then(function (response) {
                            that.$message({
                                type: response.data.code = 200 ? "success" : "error",
                                message: response.data.message
                            });
                            that.reload();
                        })
                }
            },

            checkAwards(projectId, workName, project) {
                // 发送请求检查关联的 awards 表内容
                this.$axios.get(api + `/student/getAwards/${projectId}`)
                    .then(response => {
                        // 如果查询结果为空，则显示评奖弹窗
                        if (response.data.length === 0) {
                            this.awardFormVisible = true;
                            this.setAwardFormData(workName, project);
                        } else {
                            // 如果查询结果不为空，则直接显示具体内容，评奖按钮不可用
                            this.$message.warning('该项目已经有获奖情况，评奖按钮不可用。');
                            // 将查询到的奖项数据存储到 awards 数组中
                            this.awards = response.data.map(item => ({
                                level: item.level,
                            }));
                        }
                    })
                    .catch(error => {
                        console.error('Error fetching awards:', error);
                    });
            },
            setAwardFormData(workName, project) {
                this.awardForm.work = workName;
                this.awardForm.project = project,
                    this.awardForm.compName = project.projectName;
                this.awardFormVisible = true; // 显示获奖信息表单对话框
            },
            // 上传奖状成功时的回调函数
            uploadAwardSuccess(res) {
                console.log(res);
                this.awardForm.img = res.data;
            },
            submitAwardForm() {
                let that = this;
                // 构造要发送的表单数据
                let formData = {
                    project: that.awardForm.project,
                    level: that.awardForm.level,
                    awardsTime: that.awardForm.date,
                    type: that.awardForm.type,
                    imageUrl:that.awardForm.img,
                };
                // 发送 POST 请求
                that.$axios
                    .post(api + "/awards/setAwards", formData)
                    .then(function (response) {
                        // 处理响应
                        if (response.data.code === 200) {
                            that.$message.success("获奖信息提交成功！");
                            // 隐藏获奖信息表单对话框
                            that.awardFormVisible = false;
                            // 清空表单数据
                            that.awardForm = {
                                compName: '',
                                level: '',
                                date: '',
                                type: '',
                                work: '',
                                img:'',
                                project: [],
                            };
                        } else {
                            that.$message.error("提交失败：" + response.data.message);
                        }
                    })
                    .catch(function (error) {
                        console.error("提交失败：", error);
                        that.$message.error("提交失败，请稍后重试！");
                    });
            },
            getAwardName(level) {
                switch (level) {
                    case 4:
                        return '一等奖';
                    case 3:
                        return '二等奖';
                    case 2:
                        return '三等奖';
                    case 1:
                        return '参与奖';
                    default:
                        return '未知奖项';
                }
            },

        },
        filters: {
            dataTime: function (value) {
                if (value == undefined)
                    return '-';
                value = new Date(value)
                if (value instanceof Date) {
                    var d = value;
                    var year = d.getFullYear();
                    var m = d.getMonth() + 1;
                    var day = d.getDate() < 10 ? '0' + d.getDate() : d.getDate();
                    var myDate = year + '年' + m + '月 ' + day + '日';
                    return myDate;
                } else {
                    return "-";
                }
            },
        }
    }
</script>

